function sound(freq=100,duration=.1,type='sawtooth',volume=.04,end=30){if(muted)return;try{audio||=new AudioContext();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(1,end),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch{}}
function notify(text){$('toast').textContent=text;toastTime=2.3}
function rankList(){return[{name:'YOU',score:matchKills,deaths:deathCount,player:true},...bots.map(b=>({name:b.name,score:b.score,deaths:b.deaths,player:false}))].sort((a,b)=>b.score-a.score||a.deaths-b.deaths||Number(b.player)-Number(a.player))}
function rank(){return rankList().findIndex(b=>b.player)+1}
function updateHUD(){const ranks=rankList(),r=rank();$('round').textContent=String(round).padStart(2,'0');$('timer').textContent=`${Math.floor(time/60)}:${String(Math.ceil(time%60)%60).padStart(2,'0')}`;$('rank').textContent=`${r}${['ST','ND','RD'][r-1]||'TH'} / 6`;$('health').textContent=Math.ceil(health);$('healthbar').style.width=`${health/(perks.armor?140:100)*100}%`;$('focusbar').style.width=`${focus}%`;$('focuslabel').textContent=slow?'ACTIVE':focus<10?'CHARGING':'READY';$('ammo').textContent=reloading?'—':ammo;$('weaponname').textContent=`${weapons[equipped].name} / ${weapons[equipped].label.toUpperCase()}`;$('utility').textContent=`R RELOAD · G FRAG ×${grenades} · F ${streakReady?'AIRSTRIKE READY':`${streak}/3 STREAK`}`;$('leaderboard').innerHTML=ranks.map((b,i)=>`<div class="score-row ${b.player?'you':''} ${i===2?'cutoff':''}"><span>${i+1} &nbsp;${b.name}</span><b>${b.score}</b></div>`).join('')}
function spawnBot(b){const s=spawnPoints[Math.floor(Math.random()*spawnPoints.length)];b.pos.set(s[0],0,s[2]);b.hp=100;b.dead=0;b.group.visible=true;b.group.position.copy(b.pos);b.cool=1+Math.random();for(const p of Object.values(b.parts))p.visible=true;b.target=null;b.stuck=0;b.path=[];b.navTime=0;b.vy=0}
