function showShop(){mode='shop';$('panel').hidden=false;$('panel').innerHTML=`<div class="topline"><span>UPGRADES</span><span class="credits">${credits} CR</span></div><h2>UPGRADES</h2><p>Round ${round+1} next. Upgrades last for this run.</p><div class="shop">${upgrades.map(u=>{const has=u.gun!==undefined?owned.includes(u.gun):perks[u.id];return `<button class="item" data-buy="${u.id}" ${has||credits<u.price?'disabled':''}><span class="category">${u.category}</span><strong>${u.name}</strong><span class="desc">${u.desc}</span><span class="price">${has?'OWNED ✓':`${u.price} CR ↗`}</span></button>`}).join('')}</div><div class="panel-actions"><button class="primary" id="nextmatch">START ROUND ${round+1} <span>↗</span></button><button class="textbutton" id="savequit">SAVE & EXIT</button></div>`;$('panel').querySelectorAll('[data-buy]').forEach(btn=>btn.onclick=()=>{const u=upgrades.find(x=>x.id===btn.dataset.buy);if(!u||credits<u.price)return;credits-=u.price;if(u.gun!==undefined){owned.push(u.gun);equipped=u.gun;buildWeapon()}else perks[u.id]=true;sound(350,.15,'triangle',.04,700);saveRun();showShop()});$('nextmatch').onclick=()=>{round++;startMatch(true)};$('savequit').onclick=()=>{saveRun();mainMenu()}}
function mainMenu(){mode='menu';document.exitPointerLock?.();$('panel').hidden=true;$('hud').hidden=true;$('menu').hidden=false;document.body.classList.remove('playing');weaponGroup.visible=false;$('continue').hidden=!localStorage.getItem('dh-run')}
function pause(){if(mode!=='play')return;mouseDown=false;keys.clear();slow=false;$('slowTint').style.opacity=0;$('panel').hidden=false;$('panel').innerHTML=`<div class="topline"><span>DEAD HEAT / ROUND ${round}</span><span>PAUSED</span></div><h2>PAUSED</h2><p></p>${controlsHTML()}<div class="panel-actions"><button class="primary" id="resume">RESUME <span>↗</span></button><button class="textbutton" id="quit">END RUN</button></div>`;$('resume').onclick=()=>{lock()};$('quit').onclick=()=>{localStorage.removeItem('dh-run');mainMenu()}}
function controlsHTML(){return '<dl class="controls"><dt>W A S D</dt><dd>Move · Shift to sprint</dd><dt>MOUSE</dt><dd>Look · Left click to fire · Right click to aim</dd><dt>SPACE</dt><dd>Jump · Yellow pads launch you to upper lanes</dd><dt>HOLD Q</dt><dd>Slow time · Recharges while inactive</dd><dt>R / G / F</dt><dd>Reload / Throw frag / Call earned airstrike</dd><dt>1 – 6 / WHEEL</dt><dd>Switch owned weapons</dd><dt>ESC / TAB</dt><dd>Pause / Show scoreboard</dd></dl>'}
$('start').onclick=()=>startMatch();$('continue').hidden=!localStorage.getItem('dh-run');$('continue').onclick=()=>{try{const s=JSON.parse(localStorage.getItem('dh-run'));round=s.round;credits=s.credits;owned=s.owned;equipped=s.equipped;perks=s.perks;buildWeapon();$('menu').hidden=true;document.body.classList.add('playing');s.phase==='shop'?showShop():startMatch(true)}catch{startMatch()}};
$('help').onclick=e=>{e.preventDefault();$('panel').hidden=false;$('panel').innerHTML=`<div class="topline"><span>CONTROLS</span><span></span></div><h2>CONTROLS</h2><p>90-second free-for-all. Finish in the top 3 to advance. Deaths respawn you; ties favor fewer deaths. Get 3 kills without dying to earn an airstrike.</p>${controlsHTML()}<p>Rockets deal splash damage and propel you upward: jump, look down, fire. Rail shots pierce contenders. The shotgun keeps four pellets tight for range and spreads eight for close encounters.</p><p class="warning">Mouse and keyboard recommended. Click Enter the Arena to capture your mouse. Escape releases it.</p><button class="primary" id="closehelp">BACK <span>↗</span></button>`;$('closehelp').onclick=()=>{$('panel').hidden=true}};
$('sound').onclick=()=>{muted=!muted;$('sound').innerHTML=`SOUND <span>${muted?'OFF':'ON'} ↗</span>`};
document.addEventListener('pointerlockchange',()=>{if(dragLook)return;locked=document.pointerLockElement===renderer.domElement;if(locked&&mode==='play'){$('panel').hidden=true}else if(!locked&&mode==='play')pause()});document.addEventListener('pointerlockerror',enableDragLook);
document.addEventListener('mousemove',e=>{if(!locked||mode!=='play'||(dragLook&&!e.buttons))return;const sense=keys.has('MouseRight')?.001:.002;yaw-=e.movementX*sense;pitch=clamp(pitch-e.movementY*sense,-1.5,1.5)});
document.addEventListener('mousedown',e=>{if(mode!=='play'||!locked)return;if(e.button===0)mouseDown=true;if(e.button===2)keys.add('MouseRight')});document.addEventListener('mouseup',e=>{if(e.button===0)mouseDown=false;if(e.button===2)keys.delete('MouseRight')});document.addEventListener('contextmenu',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(mode!=='play'||!locked)return;if(e.code==='Escape'&&dragLook){locked=false;pause();return}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Tab','KeyQ'].includes(e.code))e.preventDefault();if(e.code==='Tab')$('leaderboard').style.fontSize='16px';if(!e.repeat){if(e.code==='KeyR')reload();if(e.code==='KeyG'&&grenades>0&&respawnTime<=0){grenades--;camera.getWorldDirection(aim);launchRocket(playerPos,aim,null,true);sound(180,.1,'triangle',.03,90)}if(e.code==='KeyF'&&streakReady&&respawnTime<=0){streakReady=false;streak=0;notify('AIRSTRIKE INBOUND');for(const b of bots.filter(b=>!b.dead)){const pos=b.pos.clone().add(new THREE.Vector3(0,.5,0));explode(pos,null)}}const n=Number(e.key)-1;if(n>=0&&n<6)switchWeapon(n)}keys.add(e.code)});
document.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Tab')$('leaderboard').style.fontSize='11px'});window.addEventListener('blur',()=>{keys.clear();mouseDown=false;if(locked){if(dragLook){locked=false;pause()}else document.exitPointerLock()}});document.addEventListener('wheel',e=>{if(mode==='play'&&locked){const idx=owned.indexOf(equipped);switchWeapon(owned[(idx+(e.deltaY>0?1:owned.length-1))%owned.length])}},{passive:true});window.addEventListener('resize',()=>{if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
init();
